INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '特殊食品生产', '易', '是', NULL, '食品生产企业生产线监控应当避免使用水银温度计，以免破损后造成玻璃异物污染以及汞化学污染。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
