INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '特殊食品生产', '易', '是', NULL, '食品生产企业应建立食品原料、食品添加剂和食品相关产品的采购、验收、运输和贮存管理制度。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
